import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const i="/images/cliente/pedido-confirmado.png",s="/images/cliente/perfil-pedidos.png",f=JSON.parse('{"title":"7. Seguimiento de Pedidos, Facturación, Devoluciones y Garantías","description":"","frontmatter":{},"headers":[],"relativePath":"cliente/pedidos.md","filePath":"cliente/pedidos.md"}'),n={name:"cliente/pedidos.md"};function l(d,e,c,u,p,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_7-seguimiento-de-pedidos-facturacion-devoluciones-y-garantias" tabindex="-1">7. Seguimiento de Pedidos, Facturación, Devoluciones y Garantías <a class="header-anchor" href="#_7-seguimiento-de-pedidos-facturacion-devoluciones-y-garantias" aria-label="Permalink to &quot;7. Seguimiento de Pedidos, Facturación, Devoluciones y Garantías&quot;">​</a></h1><p>¡Gracias por comprar en PayMe Panamá! Esta guía te explica detalladamente cómo saber dónde está tu paquete en todo momento, cómo descargar tu factura fiscal y qué hacer paso a paso si necesitas cambiar un producto o solicitar una devolución.</p><hr><h2 id="_7-1-pantalla-de-confirmacion-y-tu-numero-de-pedido" tabindex="-1">7.1 Pantalla de Confirmación y Tu Número de Pedido <a class="header-anchor" href="#_7-1-pantalla-de-confirmacion-y-tu-numero-de-pedido" aria-label="Permalink to &quot;7.1 Pantalla de Confirmación y Tu Número de Pedido&quot;">​</a></h2><p>Apenas se completa tu pago, la pantalla te muestra la confirmación inmediata de tu compra:</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Pantalla de Pedido Confirmado</span><span class="screenshot-url">https://pyme.rsfsecure.site/pedidos/.../confirmacion</span></div><div class="screenshot-body"><img src="'+i+'" alt="Pantalla de Pedido Confirmado"></div></div><h3 id="datos-clave-que-veras-en-pantalla" tabindex="-1">Datos clave que verás en pantalla: <a class="header-anchor" href="#datos-clave-que-veras-en-pantalla" aria-label="Permalink to &quot;Datos clave que verás en pantalla:&quot;">​</a></h3><ul><li><strong>Número de Pedido:</strong> Un código único con formato <code>#ORD-2026-XXXX</code>. Este número es tu identificación principal para cualquier consulta con nuestro equipo de atención o para trámites de garantía.</li><li><strong>Resumen de Entrega:</strong> La dirección exacta y el número telefónico donde llegará tu mercancía.</li><li><strong>Método de Pago Utilizado:</strong> Confirmación de cobro por Yappy, tarjeta o transferencia bancaria.</li><li><strong>Confirmación por Correo:</strong> En cuestión de segundos recibirás un recibo de compra en tu correo electrónico registrado.</li></ul><hr><h2 id="_7-2-como-consultar-el-historial-y-el-estado-de-tus-compras" tabindex="-1">7.2 Cómo Consultar el Historial y el Estado de tus Compras <a class="header-anchor" href="#_7-2-como-consultar-el-historial-y-el-estado-de-tus-compras" aria-label="Permalink to &quot;7.2 Cómo Consultar el Historial y el Estado de tus Compras&quot;">​</a></h2><p>Puedes revisar tus compras anteriores y pedidos activos en cualquier momento:</p><ol><li>Inicia sesión en la tienda con tu usuario.</li><li>Haz clic en tu nombre en la parte superior derecha y selecciona <strong>&quot;Mis Pedidos&quot;</strong> (o ingresa directo a <a href="https://pyme.rsfsecure.site/cliente/pedidos" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/cliente/pedidos</a>).</li><li>Verás la lista ordenada con tu compra más reciente en primer lugar.</li></ol><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Historial de Compras y Seguimiento de Entrega</span><span class="screenshot-url">https://pyme.rsfsecure.site/cliente/pedidos</span></div><div class="screenshot-body"><img src="'+s+'" alt="Historial de Compras y Seguimiento de Entrega"></div></div><hr><h2 id="_7-3-estados-del-pedido-¿que-significa-cada-fase" tabindex="-1">7.3 Estados del Pedido: ¿Qué significa cada fase? <a class="header-anchor" href="#_7-3-estados-del-pedido-¿que-significa-cada-fase" aria-label="Permalink to &quot;7.3 Estados del Pedido: ¿Qué significa cada fase?&quot;">​</a></h2><p>Cada compra cuenta con una barra de avance visual que te indica en qué etapa se encuentra:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Estado del Pedido</th><th style="text-align:left;">¿Qué significa internamente?</th><th style="text-align:left;">¿Qué debes hacer tú como comprador?</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Pendiente de Pago</strong></td><td style="text-align:left;">Si elegiste transferencia ACH, el sistema está esperando la confirmación bancaria del depósito.</td><td style="text-align:left;">Si aún no subiste tu comprobante, súbelo en la página o envíalo a nuestro WhatsApp de atención.</td></tr><tr><td style="text-align:left;"><strong>Pagado / Confirmado</strong></td><td style="text-align:left;">El pago fue validado con éxito y la orden ingresó a la cola de preparación.</td><td style="text-align:left;">Nada, el personal de bodega ya recibió la lista de artículos para empacar.</td></tr><tr><td style="text-align:left;"><strong>En Preparación</strong></td><td style="text-align:left;">El equipo de almacén está retirando tus productos del estante y colocándoles protección adecuada contra golpes.</td><td style="text-align:left;">Tu paquete está listo para ser rotulado y entregado al transportista.</td></tr><tr><td style="text-align:left;"><strong>En Camino</strong></td><td style="text-align:left;">Tu compra ya salió de bodega en ruta con el mensajero local o con la empresa de envíos nacional.</td><td style="text-align:left;">Recibirás el nombre del transportista y tu <strong>Número de Guía</strong> para rastrear la entrega.</td></tr><tr><td style="text-align:left;"><strong>Entregado</strong></td><td style="text-align:left;">El paquete fue recibido en tu dirección o retirado en la sucursal de paquetería seleccionada.</td><td style="text-align:left;">¡Abre tu paquete y disfruta tu compra! Guarda tu factura digital para respaldo de garantía.</td></tr><tr><td style="text-align:left;"><strong>Cancelado</strong></td><td style="text-align:left;">El pedido fue anulado a solicitud del cliente o por falta de pago bancario en el plazo acordado.</td><td style="text-align:left;">Si ya habías pagado, se emite el reembolso correspondiente según las políticas de devolución.</td></tr></tbody></table><hr><h2 id="_7-4-tiempos-estimados-de-entrega-en-panama" tabindex="-1">7.4 Tiempos Estimados de Entrega en Panamá <a class="header-anchor" href="#_7-4-tiempos-estimados-de-entrega-en-panama" aria-label="Permalink to &quot;7.4 Tiempos Estimados de Entrega en Panamá&quot;">​</a></h2><ul><li><strong>Ciudad de Panamá y San Miguelito:</strong> De 24 a 48 horas hábiles después de confirmado el pago.</li><li><strong>Panamá Oeste (Arraiján, La Chorrera, Capira):</strong> De 24 a 48 horas hábiles.</li><li><strong>Provincias Centrales, Colón y Chiriquí:</strong> De 48 a 72 horas hábiles mediante empresas de transporte certificadas (Uno Express o Servientrega).</li><li><strong>Bocas del Toro y Darién:</strong> De 3 a 5 días hábiles según la frecuencia de paquetería de la zona.</li></ul><hr><h2 id="_7-5-como-rastrear-tu-paquete-con-el-numero-de-guia" tabindex="-1">7.5 Cómo Rastrear tu Paquete con el Número de Guía <a class="header-anchor" href="#_7-5-como-rastrear-tu-paquete-con-el-numero-de-guia" aria-label="Permalink to &quot;7.5 Cómo Rastrear tu Paquete con el Número de Guía&quot;">​</a></h2><p>Cuando tu compra pase al estado <strong>&quot;En Camino&quot;</strong>:</p><ol><li>Entra a <strong>&quot;Mis Pedidos&quot;</strong>.</li><li>En la tarjeta de tu orden verás el nombre de la empresa de logística y un <strong>Número de Guía / Tracking</strong>.</li><li>Consulta el avance según el medio de transporte: <ul><li><strong>Servientrega Panamá:</strong> Copia el número de guía e ingrésalo en la sección de rastreo de su sitio web oficial para ver las estaciones por donde va tu bulto.</li><li><strong>Uno Express:</strong> Puedes rastrearlo en su portal en línea o retirar directamente en la sucursal asignada presentando tu número de guía y tu cédula de identidad.</li><li><strong>Mensajero Local en Ciudad de Panamá:</strong> El motorizado te contactará vía llamada o WhatsApp a tu teléfono registrado antes de llegar a tu domicilio o garita.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Nota: ¿No puedes recibir personalmente el paquete?</p><p>Si trabajas o no vas a estar en tu domicilio, puedes autorizar a un familiar, conserje o agente de garita. Simplemente escribe por WhatsApp a nuestro equipo indicando el nombre completo y cédula de la persona autorizada para que el mensajero se lo entregue sin retrasos.</p></div><hr><h2 id="_7-6-como-descargar-tu-factura-fiscal-oficial-pdf" tabindex="-1">7.6 Cómo Descargar tu Factura Fiscal Oficial (PDF) <a class="header-anchor" href="#_7-6-como-descargar-tu-factura-fiscal-oficial-pdf" aria-label="Permalink to &quot;7.6 Cómo Descargar tu Factura Fiscal Oficial (PDF)&quot;">​</a></h2><p>Todas las ventas en PayMe Panamá generan una factura con valor fiscal oficial con el <strong>7% de ITBMS</strong> desglosado, válida para tu contabilidad personal, deducción de gastos empresariales y trámites de garantía directa con los centros autorizados de la marca en Panamá:</p><ol><li>Entra a <strong>&quot;Mis Pedidos&quot;</strong> (<a href="https://pyme.rsfsecure.site/cliente/pedidos" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/cliente/pedidos</a>).</li><li>Localiza la compra que deseas justificar.</li><li>Haz clic en el botón azul <strong>&quot;Descargar Factura (PDF)&quot;</strong>.</li><li>El archivo se guardará automáticamente en tu dispositivo listo para imprimir o enviar por correo a tu contador.</li></ol><hr><h2 id="_7-7-procedimiento-completo-de-devoluciones-y-garantias" tabindex="-1">7.7 Procedimiento Completo de Devoluciones y Garantías <a class="header-anchor" href="#_7-7-procedimiento-completo-de-devoluciones-y-garantias" aria-label="Permalink to &quot;7.7 Procedimiento Completo de Devoluciones y Garantías&quot;">​</a></h2><p>Comprendemos que en las compras por internet pueden surgir dudas, errores de selección o inconvenientes de transporte. Nuestra política de garantía te respalda en cada situación:</p><h3 id="caso-1-compre-por-error-me-equivoque-de-modelo-color-o-talla" tabindex="-1">Caso 1: Compré por error (Me equivoqué de modelo, color o talla) <a class="header-anchor" href="#caso-1-compre-por-error-me-equivoque-de-modelo-color-o-talla" aria-label="Permalink to &quot;Caso 1: Compré por error (Me equivoqué de modelo, color o talla)&quot;">​</a></h3><p>Si te diste cuenta de un error después de pagar:</p><ul><li><strong>Si el pedido aún está &quot;En Preparación&quot;:</strong> Contáctanos de inmediato por WhatsApp antes de las 2:00 p.m. Podemos modificar el artículo en tu pedido o anularlo sin ningún costo ni penalización para que compres el correcto.</li><li><strong>Si ya recibiste el producto:</strong> Dispones de hasta <strong>7 días calendario</strong> a partir de la fecha de entrega para solicitar un cambio.</li><li><strong>Requisitos indispensables para cambio por error:</strong><ol><li>El producto debe estar completamente nuevo, sin uso y sin signos de desgaste.</li><li>Debe conservar su caja original, empaques plásticos, manuales y todos los accesorios incluidos.</li><li>Los sellos de fábrica de la caja deben permanecer intactos en artículos de electrónica, higiene y software.</li></ol></li></ul><h3 id="caso-2-el-producto-llego-con-falla-tecnica-o-defecto-de-fabrica" tabindex="-1">Caso 2: El producto llegó con falla técnica o defecto de fábrica <a class="header-anchor" href="#caso-2-el-producto-llego-con-falla-tecnica-o-defecto-de-fabrica" aria-label="Permalink to &quot;Caso 2: El producto llegó con falla técnica o defecto de fábrica&quot;">​</a></h3><p>Si al abrir el producto notas que no enciende, no carga, tiene un fallo de funcionamiento o un desperfecto de manufactura:</p><ul><li>Tienes respaldo directo de garantía por un período de <strong>30 días a 1 año</strong> (según la marca del producto y especificaciones de la ficha técnica).</li><li>Nos encargamos de coordinar la revisión técnica oficial y el reemplazo inmediato de la unidad sin costo para ti.</li></ul><h3 id="caso-3-el-paquete-llego-golpeado-por-el-transporte-o-recibiste-un-articulo-diferente" tabindex="-1">Caso 3: El paquete llegó golpeado por el transporte o recibiste un artículo diferente <a class="header-anchor" href="#caso-3-el-paquete-llego-golpeado-por-el-transporte-o-recibiste-un-articulo-diferente" aria-label="Permalink to &quot;Caso 3: El paquete llegó golpeado por el transporte o recibiste un artículo diferente&quot;">​</a></h3><ul><li>Si la caja exterior llega visiblemente rota, aplastada o abierta por el transportista, toma fotografías antes de abrirla y repórtalo el mismo día de la recepción.</li><li>Si el modelo entregado no coincide con lo que pagaste en la factura (ejemplo: pediste 256GB y llegó de 128GB), gestionamos la recogida urgente y te enviamos el correcto de forma prioritaria.</li></ul><hr><h2 id="_7-8-paso-a-paso-para-solicitar-un-cambio-o-devolucion" tabindex="-1">7.8 Paso a Paso para Solicitar un Cambio o Devolución <a class="header-anchor" href="#_7-8-paso-a-paso-para-solicitar-un-cambio-o-devolucion" aria-label="Permalink to &quot;7.8 Paso a Paso para Solicitar un Cambio o Devolución&quot;">​</a></h2><p>Para iniciar tu solicitud de forma rápida y sin trámites burocráticos:</p><ol><li><strong>Paso 1: Toma fotos o video de evidencia:</strong><ul><li>Foto clara del producto completo.</li><li>Foto de la caja original y su código de barras o número de serie.</li><li>Si llegó con un golpe o daño físico, foto del empaque exterior de entrega.</li></ul></li><li><strong>Paso 2: Reporta tu caso:</strong><ul><li>Entra a <strong>&quot;Mis Pedidos&quot;</strong> y haz clic en <strong>&quot;Solicitar Soporte / Garantía&quot;</strong> en la orden afectada, o</li><li>Escríbenos directamente a nuestro <strong>WhatsApp de Atención al Cliente</strong> indicando tu número de pedido (ejemplo: <code>#ORD-2026-0042</code>) y adjuntando las fotos.</li></ul></li><li><strong>Paso 3: Evaluación rápida:</strong><ul><li>Nuestro equipo de atención revisará tu mensaje en menos de 2 horas hábiles y te proporcionará las instrucciones de entrega o retiro.</li></ul></li><li><strong>Paso 4: Envío o entrega del producto:</strong><ul><li>Si vives en Ciudad de Panamá, un mensajero recogerá el paquete en tu dirección.</li><li>Si estás en el interior del país, te enviaremos una guía de paquetería prepagada para que deposites el paquete en la sucursal de Uno Express o Servientrega más cercana.</li></ul></li><li><strong>Paso 5: Elige tu solución preferida:</strong><ul><li><strong>Opción A (Reemplazo):</strong> Te enviamos una unidad completamente nueva del producto sin costo adicional.</li><li><strong>Opción B (Crédito en Tienda):</strong> Te generamos un saldo a favor o cupón sin fecha de caducidad para que compres cualquier otro artículo de la tienda.</li><li><strong>Opción C (Reembolso de Dinero):</strong> Si el producto no tiene disponibilidad de cambio y aplica devolución, te reintegramos el 100% de tu dinero por el mismo medio en que pagaste (reversión a tarjeta de crédito, abono a Yappy o transferencia ACH).</li></ul></li></ol><hr><h2 id="_7-9-como-cancelar-un-pedido-antes-de-su-despacho" tabindex="-1">7.9 Cómo Cancelar un Pedido Antes de su Despacho <a class="header-anchor" href="#_7-9-como-cancelar-un-pedido-antes-de-su-despacho" aria-label="Permalink to &quot;7.9 Cómo Cancelar un Pedido Antes de su Despacho&quot;">​</a></h2><p>Si deseas cancelar una compra realizada por error:</p><ol><li>Ingresa a <strong>&quot;Mis Pedidos&quot;</strong>.</li><li>Si la orden se encuentra todavía en estado <strong>&quot;Confirmado&quot;</strong> o <strong>&quot;En Preparación&quot;</strong>, verás disponible el botón <strong>&quot;Solicitar Cancelación&quot;</strong>.</li><li>Confirma el motivo de la cancelación.</li><li>Si el pago ya había sido procesado, el sistema iniciará el proceso de devolución automática de tu dinero.</li><li>Si el paquete ya figura como <strong>&quot;En Camino&quot;</strong>, ya se encuentra en manos de la empresa de transporte y deberá seguir el procedimiento habitual de devolución una vez recibido.</li></ol><hr><h2 id="_7-10-preguntas-frecuentes-sobre-devoluciones-y-garantias" tabindex="-1">7.10 Preguntas Frecuentes sobre Devoluciones y Garantías <a class="header-anchor" href="#_7-10-preguntas-frecuentes-sobre-devoluciones-y-garantias" aria-label="Permalink to &quot;7.10 Preguntas Frecuentes sobre Devoluciones y Garantías&quot;">​</a></h2><details class="details custom-block"><summary>¿Cuánto tiempo demora en verse reflejado mi reembolso bancario?</summary><ul><li><strong>Pagos con Yappy:</strong> Se reintegran a tu número de Banco General en un plazo de 24 a 48 horas hábiles.</li><li><strong>Transferencias ACH:</strong> Se depositan a tu cuenta bancaria en un plazo de 24 a 48 horas hábiles.</li><li><strong>Tarjetas de Crédito / Débito:</strong> La reversión se envía de inmediato al procesador del banco emisor. Dependiendo de las políticas internas de tu banco (Banco General, Banistmo, BAC, etc.), el crédito se reflejará en tu estado de cuenta entre 3 y 10 días hábiles.</li></ul></details><details class="details custom-block"><summary>¿Quién asume el costo de envío si el producto llegó defectuoso?</summary><p>Cuando el cambio se debe a un defecto de fábrica, error de envío por parte de la tienda o daño durante el transporte, <strong>PayMe Panamá asume el 100% de los costos de transporte y recolección</strong>. El comprador no tiene que pagar nada adicional.</p></details><details class="details custom-block"><summary>¿Qué productos no admiten devoluciones por cambio de parecer?</summary><p>Por normativas de salud e higiene en Panamá, no se aceptan cambios por cambio de opinión (salvo defecto de fábrica) en: artículos de uso personal como audífonos intrauditivos (in-ear), prendas íntimas, productos de cuidado personal o consumibles desprecintados.</p></details><details class="details custom-block"><summary>¿Qué ocurre si extravié la caja original del producto?</summary><p>Para aplicar a un cambio por error de compra o desistimiento es requisito indispensable contar con la caja original y accesorios. Si el producto presenta un defecto de fábrica dentro del período de garantía legal, te brindaremos servicio técnico o reemplazo respaldado por tu factura fiscal digital, aún cuando el empaque exterior no se conserve.</p></details>',54)])])}const h=a(n,[["render",l]]);export{f as __pageData,h as default};
